SELECT 'TABLE:sys_user' AS object_difference WHERE NOT COALESCE((((SELECT COUNT(*) FROM information_schema.tables WHERE BINARY table_schema=BINARY DATABASE() AND BINARY table_name='sys_user' AND table_type='BASE TABLE' AND engine='InnoDB' AND table_collation='utf8mb4_general_ci')=1)),FALSE)
UNION ALL
